package dev.ward.infrastructure.analysis.node;

import static org.assertj.core.api.Assertions.assertThat;

import dev.ward.infrastructure.json.ForyJsonCodec;
import java.io.IOException;
import java.net.URISyntaxException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;

/**
 * Checks the Node resolution against the dependency-cruiser edges committed beside each fixture.
 * The golden lists are generated by {@code DependencyCruiserEdgesSmokeTest} with a real
 * dependency-cruiser, which this offline test does not need.
 */
class NodeResolutionReferenceTest {
  private static final String GOLDEN = "depcruise-edges.json";

  @ParameterizedTest
  @ValueSource(
      strings = {
        "node-resolution",
        "turborepo-workspace",
        "node-architecture/typescript",
        "node-architecture/javascript"
      })
  void resolvedEdgesEqualTheCommittedDependencyCruiserEdges(final String fixture)
      throws IOException, URISyntaxException {
    assertThat(NodeDependencyEdgesTest.edgesOf(fixture))
        .isEqualTo(goldenEdges(NodeDependencyEdgesTest.fixture(fixture).resolve(GOLDEN)));
  }

  /** Reads the committed {@code [from, to]} pairs and sorts them the way the edges are sorted. */
  static List<String> goldenEdges(final Path golden) throws IOException {
    final Object parsed = new ForyJsonCodec().fromJson(Files.readString(golden), Object.class);
    return ((List<?>) parsed)
        .stream()
            .map(pair -> (List<?>) pair)
            .map(pair -> pair.get(0) + "->" + pair.get(1))
            .sorted()
            .toList();
  }
}
